// rankedAssertLenZeroOnError asserts Len returns zero alongside any error.
func rankedAssertLenZeroOnError(
	tb testing.TB,
	r Ranked,
) {
	tb.Helper()
	ctx, cancel := context.WithCancel(tb.Context())
	cancel()
	got, err := r.Len(ctx)
	if err == nil {
		tb.Skip("Len answered for a cancelled context, so this check has no error to inspect")
	}

	var zero int
	if got != zero {
		tb.Errorf("Len must return the zero value alongside an error: got %+v, want %+v (err %v)",
			got, zero, err)
	}
}

